function validate([jewels, stones]) {
  if (typeof jewels !== 'string' || jewels.length < 1 || jewels.length > 50) return 'jewels needs 1 to 50 characters.';
  if (typeof stones !== 'string' || stones.length < 1 || stones.length > 50) return 'stones needs 1 to 50 characters.';
  if (!/^[a-zA-Z]+$/.test(jewels) || !/^[a-zA-Z]+$/.test(stones)) return 'Both strings use only English letters.';
  if (new Set(jewels).size !== jewels.length) return 'Each character of jewels appears only once.';
  return null;
}

