function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const all = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  for (let i = all.length - 1; i > 0; i--) { const j = pick(i + 1); [all[i], all[j]] = [all[j], all[i]]; }
  const kinds = size === 'large' ? all.slice(0, 2 + pick(50)) : all.slice(0, 1 + pick(5));
  const jewels = kinds.slice(0, 1 + pick(Math.min(kinds.length, 50))).join('');
  const length = size === 'large' ? 50 : 1 + pick(10);
  const stones = Array.from({ length }, () => kinds[pick(kinds.length)]).join('');
  return [jewels, stones];
}
